package app.jarvis.core.voice;

import java.nio.charset.StandardCharsets;

/**
 * Bit-exact Java port of the edge-tts drm.py construction for the Microsoft Sec-MS-GEC v2 token:
 * a custom SHA-256 variant (adjusted initial state / schedule / round constants) combined with a
 * CS64 checksum. Validated against reference vectors generated by the Python original
 * (.cache/research/edge_tts_pkg/run_ref.py) — see SecMsGecTest.
 *
 * All arithmetic is 32-bit wrapping (Java int), matching Python's &amp; 0xFFFFFFFF masking.
 */
public final class SecMsGec {
    private SecMsGec() { }

    public static final String TRUSTED_CLIENT_TOKEN = "6A5AA1D4EAFF4E9FB37E23D68491D6F4";
    private static final long WIN_EPOCH = 11644473600L;

    private static final int[] SHA256_INITIAL = {
        0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A, 0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19 };
    private static final int[] SHA256_STATE = {
        0xFD9FBEA2, 0x91243CE7, 0xBE499094, 0xCD2E1E0A, 0x6C006F49, 0x04BD35AB, 0xFEB0A7E4, 0x03EFFBD2 };
    private static final int[] SHA256_SCHEDULE = {
        0xEB24BF9E, 0x1558691F, 0xA0C09EE2, 0x0CFA32BA, 0xA622EE8C, 0xD1DD9491, 0xC0DD25A0, 0xF9E70AB6,
        0xF0C31573, 0x7058CE4E, 0x7188E606, 0x00E5AB33, 0xD258B060, 0x72766564 };
    private static final int[] RC = {
        0x428A2F98, 0x71374491, 0xB5C0FBCF, 0xE9B5DBA5, 0x3956C25B, 0x59F111F1, 0x923F82A4, 0xAB1C5ED5,
        0xD807AA98, 0x12835B01, 0x243185BE, 0x550C7DC3, 0x72BE5D74, 0x80DEB1FE, 0x9BDC06A7, 0xC19BF174,
        0xE49B69C1, 0xEFBE4786, 0x0FC19DC6, 0x240CA1CC, 0x2DE92C6F, 0x4A7484AA, 0x5CB0A9DC, 0x76F988DA,
        0x983E5152, 0xA831C66D, 0xB00327C8, 0xBF597FC7, 0xC6E00BF3, 0xD5A79147, 0x06CA6351, 0x14292967,
        0x27B70A85, 0x2E1B2138, 0x4D2C6DFC, 0x53380D13, 0x650A7354, 0x766A0ABB, 0x81C2C92E, 0x92722C85,
        0xA2BFE8A1, 0xA81A664B, 0xC24B8B70, 0xC76C51A3, 0xD192E819, 0xD6990624, 0xF40E3585, 0x106AA070,
        0x19A4C116, 0x1E376C08, 0x2748774C, 0x34B0BCB5, 0x391C0CB3, 0x4ED8AA4A, 0x5B9CCA4F, 0x682E6FF3,
        0x748F82EE, 0x78A5636F, 0x84C87814, 0x8CC70208, 0x90BEFFFA, 0xA4506CEB, 0xBEF9A3F7, 0xC67178F2 };
    private static final int SHA256_ADJUSTMENT = 0xC9DC06A7;
    private static final int SIGMA0_ADJUSTMENT = 0x059C0B80;
    private static final int SIGMA1_ADJUSTMENT = 0x000B92C0;

    private static final int[][] CS64_COEFFICIENTS = {
        { 0xE82E91B1, 0xB32700D0 }, { 0x44DE24C6, 0x88DFF51D }, { 0x3BEB65BC, 0x29514038 },
        { 0xC89C5933, 0xB328CBDF }, { 0x8D1EC211, 0xD405B4D5 }, { 0x314EF5D5, 0x26E55F3C },
        { 0xE92491B1, 0x607801C6 }, { 0xF0A5B9D5, 0x82B2C1FB }, { 0x06064CF3, 0xFA51A3DA },
        { 0xDA79FA60, 0x207CC464 }, { 0xBED20560, 0x3C3C74F3 }, { 0x89F9C9F8, 0xD2D14B61 },
        { 0x35FA38C6, 0xBB04A2C1 }, { 0xCB49E3C6, 0xC5626167 } };
    private static final int CS64_FACTOR = 0x82893933;
    private static final int CS64_ADJUSTMENT0 = 0xF2F90B1A;
    private static final int CS64_ADJUSTMENT1 = 0x0B1A0000;

    /** ROTR(x,7)^ROTR(x,18)^SHR(x,3) of the custom variant (equivalent to the Python combined form). */
    private static int sigma0(int v) {
        return (v >>> 7) ^ (v << 25) ^ (v >>> 18) ^ (v << 14) ^ (v >>> 3);
    }

    private static int sigma1(int v) {
        return (v >>> 17) ^ (v << 15) ^ (v >>> 19) ^ (v << 13) ^ (v >>> 10);
    }

    private static int rol16(int v) { return Integer.rotateLeft(v, 16); }

    /** Standard SHA-256 message-schedule expansion with the custom constants folded in. */
    private static void expandSchedule(int[] w, int first) {
        for (int i = first; i < 64; i++) {
            int x = w[i - 2], y = w[i - 15];
            w[i] = sigma1(x) + w[i - 7] + sigma0(y) + w[i - 16];
        }
    }

    /** SHA-256 compression (custom constants); rounds before {@code first} are skipped. */
    private static int[] rounds(int[] st, int[] w, int first) {
        int a = st[0], b = st[1], c = st[2], d = st[3], e = st[4], f = st[5], g = st[6], h = st[7];
        for (int i = first; i < 64; i++) {
            // the adjusted constant is only used when resuming inside the first (init) block
            int k = first == 14 && i == 14 ? SHA256_ADJUSTMENT : RC[i];
            int t1 = h + (Integer.rotateRight(e, 6) ^ Integer.rotateRight(e, 11) ^ Integer.rotateRight(e, 25))
                + (g ^ (e & (f ^ g))) + k + w[i];
            int t2 = (Integer.rotateRight(a, 2) ^ Integer.rotateRight(a, 13) ^ Integer.rotateRight(a, 22))
                + ((a & b) | (c & (a | b)));
            h = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
        }
        return new int[] { a, b, c, d, e, f, g, h };
    }

    /** Initial state for token data: a full block hashing data[0:7] with adjusted constants. */
    private static int[] sha256Init(byte[] head) {
        int[] w = new int[64];
        w[14] = ((head[0] & 0xff) << 16) | ((head[1] & 0xff) << 8) | (head[2] & 0xff);
        w[15] = ((head[3] & 0xff) << 24) | ((head[4] & 0xff) << 16) | ((head[5] & 0xff) << 8) | (head[6] & 0xff);
        for (int i = 16; i < 30; i++) {
            int value = SHA256_SCHEDULE[i - 16];
            if (i - 2 >= 14) value += i == 16 ? (sigma1(w[i - 2]) ^ SIGMA1_ADJUSTMENT) : sigma1(w[i - 2]);
            if (i - 7 >= 14) value += w[i - 7];
            if (i - 15 >= 14) value += i == 29 ? (sigma0(w[i - 15]) ^ SIGMA0_ADJUSTMENT) : sigma0(w[i - 15]);
            w[i] = value;
        }
        w[30] = sigma1(w[28]) + w[23] + sigma0(w[15]) + w[14] + SHA256_ADJUSTMENT - RC[14];
        expandSchedule(w, 31);
        int[] working = rounds(SHA256_STATE, w, 14);
        for (int i = 0; i < 8; i++) working[i] += SHA256_INITIAL[i];
        return working;
    }

    /** The custom SHA-256 digest of the token string (must be at least 7 bytes). */
    static byte[] sha256Digest(byte[] data) {
        if (data.length < 7) throw new IllegalArgumentException("token salt must contain at least seven bytes");
        int length = 57 + data.length;
        int tail = data.length - 7;
        int zeros = Math.floorMod(55 - length, 64);
        byte[] padded = new byte[tail + 1 + zeros + 8];
        System.arraycopy(data, 7, padded, 0, tail);
        padded[tail] = (byte) 0x80;
        long bits = length * 8L;
        for (int i = 0; i < 8; i++) padded[padded.length - 1 - i] = (byte) (bits >>> (8 * i));

        int[] state = sha256Init(data);
        int[] w = new int[64];
        for (int off = 0; off < padded.length; off += 64) {
            for (int i = 0; i < 16; i++) {
                int p = off + 4 * i;
                w[i] = ((padded[p] & 0xff) << 24) | ((padded[p + 1] & 0xff) << 16) | ((padded[p + 2] & 0xff) << 8) | (padded[p + 3] & 0xff);
            }
            expandSchedule(w, 16);
            int[] working = rounds(state, w, 0);
            for (int i = 0; i < 8; i++) state[i] += working[i];
        }
        byte[] out = new byte[32];
        for (int i = 0; i < 8; i++) {
            out[4 * i] = (byte) (state[i] >>> 24);
            out[4 * i + 1] = (byte) (state[i] >>> 16);
            out[4 * i + 2] = (byte) (state[i] >>> 8);
            out[4 * i + 3] = (byte) (int) state[i];
        }
        return out;
    }

    /** CS64: two u32 words derived from the data and the digest. */
    static int[] cs64(byte[] data, byte[] digest) {
        int keyA = ((digest[0] & 0xff) | (digest[1] & 0xff) << 8 | (digest[2] & 0xff) << 16 | (digest[3] & 0xff) << 24) | 1;
        int keyB = ((digest[4] & 0xff) | (digest[5] & 0xff) << 8 | (digest[6] & 0xff) << 16 | (digest[7] & 0xff) << 24) | 1;
        int fA = keyA * CS64_FACTOR, fB = keyB * CS64_FACTOR;

        int n = 1 + data.length;
        int paddedWords = (n + 3) / 4 + (n % 2); // zero-padded to 4, then even word count
        int[] terms = new int[CS64_COEFFICIENTS.length + paddedWords];
        int[] offsets = new int[CS64_COEFFICIENTS.length + paddedWords];
        for (int i = 0; i < CS64_COEFFICIENTS.length; i++) {
            terms[i] = CS64_COEFFICIENTS[i][0] * (i % 2 == 0 ? fA : fB);
            offsets[i] = CS64_COEFFICIENTS[i][1];
        }
        // words of (0x00 + data), little-endian, zero-padded to even count
        byte[] prefixed = new byte[n];
        prefixed[0] = 0;
        System.arraycopy(data, 0, prefixed, 1, data.length);
        int words = (prefixed.length + 3) / 4;
        if (words % 2 != 0) words++;
        for (int i = 0; i < words; i++) {
            int p = 4 * i;
            int word = p < prefixed.length ? (prefixed[p] & 0xff) : 0;
            if (p + 1 < prefixed.length) word |= (prefixed[p + 1] & 0xff) << 8;
            if (p + 2 < prefixed.length) word |= (prefixed[p + 2] & 0xff) << 16;
            if (p + 3 < prefixed.length) word |= (prefixed[p + 3] & 0xff) << 24;
            int term = word * (i % 2 == 0 ? keyA : keyB);
            int offset = rol16(word) * (i % 2 == 0 ? 0xEF0569FB : 0xC31713DB);
            if (i == 0) { term += CS64_ADJUSTMENT0 * fA; offset += CS64_ADJUSTMENT1; }
            terms[CS64_COEFFICIENTS.length + i] = term;
            offsets[CS64_COEFFICIENTS.length + i] = offset;
        }

        int swapAcc = 0, swapLast = 0, state = 0, acc = 0;
        for (int i = 0; i < terms.length; i += 2) {
            int x = terms[i], y = terms[i + 1];
            int t = rol16(offsets[i] + x);
            int q = t * 0x76F50F34;
            swapAcc += rol16(q) * 0xC3EFEA97 + q;
            t = rol16(offsets[i + 1] + y);
            q = t * 0x1881CE3C;
            swapLast = rol16(q) * 0x35BD1EC9 + q;
            swapAcc += swapLast;

            state = state * keyA + x;
            state = rol16(state) * 0xCF98B111;
            state = rol16(state) * 0x87085B9F;
            state = rol16(state) * 0x12CEB96D;
            state = rol16(state) * 0x257E1D83;
            acc += state;
            t = state * keyB + y;
            t = rol16(t) * 0xA27416F5;
            t = rol16(t) * 0xD38396FF;
            state = rol16(rol16(t) * 0x7C932B89) * 0xBFA49F69;
            acc += state;
        }
        return new int[] { swapLast ^ state, swapAcc ^ acc };
    }

    static String hexUpper(byte[] b) {
        StringBuilder sb = new StringBuilder(b.length * 2);
        for (byte x : b) sb.append(Character.forDigit((x >> 4) & 0xf, 16)).append(Character.forDigit(x & 0xf, 16));
        return sb.toString().toUpperCase();
    }

    private static final char[] HEX = "0123456789ABCDEF".toCharArray();

    /** "CS64-SHA256" token hash of the ASCII string, e.g. "52BC7A17...-28C43947...". */
    static String tokenHash(String s) {
        byte[] digest = sha256Digest(s.getBytes(StandardCharsets.US_ASCII));
        int[] cs = cs64(s.getBytes(StandardCharsets.US_ASCII), digest);
        StringBuilder csHex = new StringBuilder(16);
        for (int v : cs) {
            // little-endian u32s, each byte printed high-nibble first
            for (int shift = 0; shift < 32; shift += 8) {
                int b = (v >>> shift) & 0xff;
                csHex.append(HEX[b >>> 4]).append(HEX[b & 0xf]);
            }
        }
        return csHex + "-" + hexUpper(digest);
    }

    /** v2 Sec-MS-GEC token for a unix timestamp: CS64-SHA256 of the 300 s window ticks + trusted token. */
    public static String generate(long unixSeconds) {
        long ticks = unixSeconds + WIN_EPOCH;
        ticks -= ticks % 300;
        return tokenHash(Long.toString(ticks * 10_000_000L) + TRUSTED_CLIENT_TOKEN);
    }
}
